mapper.select:
LOWER(table_name) LIKE LOWER(CONCAT('%', #{tableName}, '%'))
AND LOWER(table_comment) LIKE LOWER(CONCAT('%', #{tableComment}, '%'))
AND swagger = #{swagger,jdbcType=INTEGER}
AND excel_export = #{excelExport,jdbcType=INTEGER}
AND vue_version = #{vueVersion,jdbcType=INTEGER}
AND DATE_FORMAT(create_time, '%y%m%d') >= DATE_FORMAT(#{params.beginTime,jdbcType=VARCHAR}, '%y%m%d')
AND DATE_FORMAT(create_time, '%y%m%d') <= DATE_FORMAT(#{params.endTime,jdbcType=VARCHAR}, '%y%m%d')
AND DATE_FORMAT(update_time, '%y%m%d') BETWEEN DATE_FORMAT(#{params.beginUpdateTime,jdbcType=VARCHAR}, '%y%m%d') AND DATE_FORMAT(#{params.endUpdateTime,jdbcType=VARCHAR}, '%y%m%d')
ORDER BY table_id DESC

